<?php /** @var list<array<string,mixed>> $rows */ /** @var int $total */ /** @var int $page */ /** @var int $perPage */ /** @var array<string,mixed> $filters */ /** @var array<string,mixed> $qs */ /** @var bool $canRecord */ use Vertex\Core\View;
$sel = static fn (string $a, string $b): string => $a === $b ? ' selected' : ''; ?>
<div class="page-head"><div><p class="eyebrow">Finance</p><h1>Client payments</h1></div><?php if ($canRecord) : ?><a class="btn btn-primary" href="/client-payments/new">Record a payment</a><?php endif; ?></div>
<p class="muted">Payments received from clients. Only a verified payment counts toward a referral commission, and the person who records a payment cannot verify it.</p>
<form method="get" action="/client-payments" class="toolbar" role="search"><div class="field"><label for="q">Search</label><input id="q" name="q" type="search" maxlength="100" placeholder="Reference, invoice, project" value="<?= e($filters['q']) ?>"></div>
    <div class="field"><label for="s">Status</label><select id="s" name="status"><option value="">All</option><?php foreach (['pending_verification' => 'Awaiting verification', 'verified' => 'Verified', 'reversed' => 'Reversed'] as $c => $l) : ?><option value="<?= e($c) ?>"<?= $sel($filters['status'], $c) ?>><?= e($l) ?></option><?php endforeach; ?></select></div>
    <div class="field"><label for="from">From</label><input id="from" name="from" type="date" value="<?= e($filters['from']) ?>"></div><div class="field"><label for="to">To</label><input id="to" name="to" type="date" value="<?= e($filters['to']) ?>"></div><div class="field"><button class="btn btn-ghost" type="submit">Filter</button></div></form>
<div class="table-wrap"><table class="table"><thead><tr><th>Payment</th><th>Project</th><th>Role</th><th class="num">Gross</th><th class="num">Refunded</th><th>Received</th><th>Status</th></tr></thead><tbody>
    <?php foreach ($rows as $p) : ?><tr><td><a href="/client-payments/<?= e($p['public_id']) ?>"><strong><?= e($p['reference']) ?></strong></a></td><td><?= e($p['project_code']) ?><br><span class="muted"><?= e($p['project_title']) ?></span></td><td><?= e(ucfirst($p['payment_role'])) ?></td>
        <td class="num"><?= e(money($p['gross_minor'])) ?></td><td class="num"><?= e(money($p['refunded_minor'])) ?></td><td><?= e(local_date($p['received_on'])) ?></td><td><?= View::partial('pbadge', ['kind' => 'payment', 's' => $p['status']]) ?></td></tr><?php endforeach; ?>
    <?php if ($rows === []) : ?><tr><td colspan="7" class="muted">No payments match.</td></tr><?php endif; ?></tbody></table></div>
<?= View::partial('pagination', ['page' => $page, 'perPage' => $perPage, 'total' => $total, 'filters' => $qs]) ?>
